function uniqueNodes(n){for(var r=[],e=0,t=n.length;e<t;e++){var i=n[e];r.indexOf(i[0])<0&&r.push(i[0]),r.indexOf(i[1])<0&&r.push(i[1])}return r}function sort(n,r){for(var e=n.length,t=new Array(e),i={},o=e;o--;)i[o]||f(n[o],o,[]);function f(o,u,c){if(c.indexOf(o)>=0)throw new Error("Cyclic dependency: "+JSON.stringify(o));if(!i[u]){i[u]=!0;var d=r.filter(function(n){return n[0]===o});if(u=d.length){var s=c.concat(o);do{var a=d[--u][1];f(a,n.indexOf(a),s)}while(u)}t[--e]=o}}return t}exports=function(n){return sort(uniqueNodes(n),n)},module.exports=exports;